  const injuredCount = (player: Player) => incidents.filter((incident) => incident.playerId === player.id && incident.type === "Lesionada").length;
  const suspended = (player: Player) => Boolean(player.suspensionUntil && new Date(player.suspensionUntil).getTime() > now);
