  const submit = (event: FormEvent) => {
    event.preventDefault(); if (!firstName.trim() || !lastName.trim()) return;
    const formattedFirstName = normalisePersonName(firstName); const formattedLastName = normalisePersonName(lastName);
    onAdd({ id: `manual-player-${Date.now()}`, name: `${formattedFirstName} ${formattedLastName}`, lastName: formattedLastName, nickname: normalisePersonName(nickname), avatar: avatar || undefined, email: email.trim() || undefined, phone: phone.trim() || undefined, club: club.trim() || undefined, level: level === "Sin asignar" ? undefined : level, manuallyCreated: true });
    setFirstName(""); setLastName(""); setNickname(""); setEmail(""); setPhone(""); setClub(""); setLevel("Sin asignar"); setAvatar(""); setCreating(false);
  };
